function applyOpsBatch(projectId, batch) {
	const first = useGraphStore.getState().doc;
	for (const op of batch.ops) {
		const current = useGraphStore.getState().doc;
		if (current === null || current.meta.id !== projectId) return;
		useGraphStore.getState().applyRemote(op);
	}
	const last = useGraphStore.getState().doc;
	if (batch.batchId === null || first === null || last === null || last === first) return;
	emitAgentBatch({
		batchId: batch.batchId,
		before: first,
		after: last,
		ops: batch.ops
	});
}
var DAEMON_UNREACHABLE = "Tillage daemon stopped — edits aren’t saving. Ask your agent to use Tillage (any call restarts it), then reload this page.";
async function openProjectSession(provider, projectId, options = {}) {
	const onStreamError = (err) => {
		console.error(err);
		if (provider.kind === "local") {
			useSyncStatus.setState({ streamError: DAEMON_UNREACHABLE });
			return;
		}
		useViewStore.getState().showToast("Live sync hit an error — reload to catch up");
	};
	return await provider.subscribe(projectId, {
		onOps: (batch) => {
			advanceDocCursor(projectId, batch.seq);
			applyOpsBatch(projectId, batch);
			if (batch.origin != null) {
				usePlanesStore.getState().refresh(projectId);
				useCodeFactsStore.getState().refresh(projectId);
			}
			useLookStore.getState().refresh(projectId);
		},
		onDesync: () => {
			resyncProject(provider, projectId).catch(onStreamError);
		},
		onError: onStreamError,
		onLive: () => {
			if (useSyncStatus.getState().streamError !== null) useSyncStatus.setState({ streamError: null });
		}
	}, {
		sinceSeq: getDocCursor(projectId) ?? 0,
		...options
	});
}
